#!/usr/bin/env bash
# Fixes a real bug found on an actual Windows install (Event Viewer showed
# it precisely): the Windows service wrapper (service_files/windows/
# opslab_agent_service.py) failed with "ModuleNotFoundError: No module
# named 'agent'" every time. Root cause: the Windows service framework runs
# that script with sys.path[0] set to its OWN directory
# (C:\...\OpsLabAgent\service\), not the parent install directory where
# agent/ actually lives as a sibling folder - so `from agent.main import
# run` could never succeed. Fixed by explicitly adding the parent install
# directory to sys.path before that import. Reproduced the exact
# ModuleNotFoundError on Linux first (same layout, same script, same
# failure), then confirmed the fix resolves it, before rebuilding the
# tarball install.ps1 downloads. Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (fixed service wrapper)"
base64 -d > app/static/installers/opslab-agent.tar.gz << 'B64_EOF_MARKER'

B64_EOF_MARKER

echo "==> Verifying the tarball is valid and contains the fix"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
mkdir -p /tmp/verify_fix_$$
tar -xzf app/static/installers/opslab-agent.tar.gz -C /tmp/verify_fix_$$
if grep -q "install_root" /tmp/verify_fix_$$/service_files/windows/opslab_agent_service.py; then
    echo "    Confirmed: fix is present in the packaged service wrapper."
else
    echo "    ERROR: fix not found in the extracted tarball!"
    rm -rf /tmp/verify_fix_$$
    exit 1
fi
rm -rf /tmp/verify_fix_$$

echo ""
echo "Done. Restart the app the same way as before:"
echo "    pkill -f 'admin_panel/run.py'"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > /root/admin_panel/app.log 2>&1 &"
echo ""
echo "Then on the Windows machine, uninstall the broken service and reinstall fresh"
echo "(it already downloaded the OLD tarball into C:\\Program Files\\OpsLabAgent):"
echo '    & "C:\Program Files\OpsLabAgent\python\python.exe" "C:\Program Files\OpsLabAgent\service\opslab_agent_service.py" stop'
echo '    & "C:\Program Files\OpsLabAgent\python\python.exe" "C:\Program Files\OpsLabAgent\service\opslab_agent_service.py" remove'
echo '    Remove-Item "C:\Program Files\OpsLabAgent" -Recurse -Force'
echo '    Remove-Item "C:\ProgramData\OpsLabAgent" -Recurse -Force'
echo "Then re-run the install command from the instances page (Copy button) again -"
echo "this time it will download the fixed tarball."
